// Express 5 (path-to-regexp v8): wildcards must be named; req.params.path is an array of segments.
app.get('/files/*path', (req, res) => {
  const segments = req.params.path;
  const fullPath = segments.join('/');
  const name = segments[segments.length - 1];
  const dot = name.lastIndexOf('.');
  res.json({
    path: fullPath,
    name,
    directory: segments.slice(0, -1).join('/'),
    extension: dot > 0 ? name.slice(dot + 1) : '',
    depth: segments.length,
  });
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found', path: req.path });
});
EOF
cat > test/files.test.js <<'EOF'
import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { app } from '../src/app.js';

let server;
let base;
before(() => {
  server = app.listen(0);
  base = `http://127.0.0.1:${server.address().port}`;
});
after(() => server.close());

test('GET /files/<single segment>', async () => {
  const r = await fetch(`${base}/files/readme.md`);
  assert.equal(r.status, 200);
  assert.deepEqual(await r.json(), {
    path: 'readme.md', name: 'readme.md', directory: '', extension: 'md', depth: 1,
  });
});

test('GET /files/<nested path with slashes>', async () => {
  const r = await fetch(`${base}/files/a/b/c/archive.tar.gz`);
  assert.equal(r.status, 200);
  assert.deepEqual(await r.json(), {
    path: 'a/b/c/archive.tar.gz', name: 'archive.tar.gz', directory: 'a/b/c', extension: 'gz', depth: 4,
  });
});

test('file without extension / dotfile has empty extension', async () => {
  const a = await (await fetch(`${base}/files/dir/Makefile`)).json();
  const b = await (await fetch(`${base}/files/.gitignore`)).json();
  assert.equal(a.extension, '');
  assert.equal(b.extension, '');
});

test('GET /files/ with no path is a JSON 404', async () => {
  const r = await fetch(`${base}/files/`);
  assert.equal(r.status, 404);
  assert.match(r.headers.get('content-type'), /application\/json/);
});

test('unknown route returns JSON 404', async () => {
  const r = await fetch(`${base}/nope`);
  assert.equal(r.status, 404);
  assert.match(r.headers.get('content-type'), /application\/json/);
  assert.deepEqual(await r.json(), { error: 'Not Found', path: '/nope' });
});

test('unknown method on known route is JSON 404', async () => {
  const r = await fetch(`${base}/files/x.txt`, { method: 'POST' });
  assert.equal(r.status, 404);
  assert.equal((await r.json()).error, 'Not Found');
});
EOF
